package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import android.accessibilityservice.AccessibilityServiceInfo;import java.util.*;import org.json.*;import org.w3c.dom.*;
/** Existing adding-hole mode must not become editing of the outer ring on recreation. */
final class NewHoleIntentChecks {
 final MapAndroidChecks m;final VertexRotationChecks p;final GeometryConfirmationChecks g;final ManagerVisualChecks v;final ManagerRotationChecks r;
 NewHoleIntentChecks(MapAndroidChecks m){this.m=m;p=new VertexRotationChecks(m);g=new GeometryConfirmationChecks(m);v=p.v;r=p.r;}
 String main(boolean deletion){return deletion?"0.2 4.2 51\n0.2 4.7 52\n0.5 4.7 53\n0.7 4.5 54":"0.2 4.2 51\n0.2 4.7 52\n0.7 4.7 53";}
 void snapshot(String stage,boolean keyboard)throws Exception{JSONObject o=new JSONObject();o.put("name",stage);o.put("addingHole",m.editorField("addingHole"));o.put("key",g.key());o.put("main",m.geometryInput());o.put("raw",p.state());o.put("ime",v.imeWindows());final JSONArray texts=new JSONArray();m.runOnMainSync(()->{try{v.inspect(m.activeDialogRoot(),texts);}catch(Exception e){throw new RuntimeException(e);}});o.put("texts",texts);m.capture("mvisual-newhole-"+stage);v.emit("NEWHOLE_VISUAL "+o.toString());for(int i=0;i<texts.length();i++){JSONObject t=texts.getJSONObject(i);if(t.getBoolean("visible"))m.check(t.getBoolean("arimo"),"Arimo on new-hole intent "+t.getString("text"));}if(keyboard){m.check(v.imeWindows().length()>0,"new-hole raw real IME stays present");p.physicalControlsAboveIme();v.buttonsReachable("Применить");v.editableLineVisible();}}
 void identity(long id,boolean deletion,String operation,String token,String stamp)throws Exception{Object d=m.editorField(deletion?"geometryConfirmation":"vertexDraft");m.check(d!=null&&(Boolean)m.editorField("addingHole")&&g.key().equals("0/outer"),"unsaved new-hole context is not rebound to editing the outer boundary");Class<?> c=d.getClass();m.check(c.getField("project").getLong(d)==id&&"point".equals(c.getField("feature").get(d))&&m.editorField("VERTEX_SESSION").equals(c.getField("session").get(d))&&"0/outer".equals(c.getField("key").get(d))&&token.equals(c.getField("token").get(d))&&stamp.equals(c.getField("mainStamp").get(d))&&"Polygon".equals(c.getField("type").get(d))&&c.getField("addingHole").getBoolean(d)&&c.getField("index").getInt(d)==1&&(deletion?"vertex".equals(c.getField("kind").get(d)):operation.equals(c.getField("operation").get(d))),"original new-hole owner/process/key/token/stamp/type/operation/index retained");}
 void rotate(int direction)throws Exception{Activity old=m.activity;p.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"new-hole activity actually destroyed/recreated");}
 void scenario(Object store,String operation)throws Exception{boolean deletion=operation.startsWith("delete"),save=operation.equals("after")||operation.equals("delete-save");long id=g.fixture(store,true);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.GeometryEditorActivity").putExtra("project",id).putExtra("feature","point").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));p.rotate(UiAutomation.ROTATION_FREEZE_0);m.click("Действия");m.click("Добавить внутренний контур");m.inputs(main(deletion));m.check((Boolean)m.editorField("addingHole")&&g.key().equals("0/outer"),"new-hole fixture before opening vertex intent");String token=(String)m.editorField("expected");m.click("Действия");m.click("Редактировать вершины");m.click("2. 0.2 4.7 52.0");m.click(deletion?"Удалить вершину":operation.equals("before")?"Вставить перед":"Вставить после");if(!deletion){m.inputs("0.3 4.5 99");m.runOnMainSync(()->p.field(m.activeDialogRoot()).setSelection(1,3));v.keyboard();}Object d=m.editorField(deletion?"geometryConfirmation":"vertexDraft");String stamp=(String)d.getClass().getField("mainStamp").get(d);JSONObject raw=deletion?null:p.state();identity(id,deletion,operation,token,stamp);snapshot(operation+"-before",!deletion);rotate(UiAutomation.ROTATION_FREEZE_90);if(!deletion)v.keyboard();identity(id,deletion,operation,token,stamp);if(!deletion)p.sameRaw(raw);snapshot(operation+"-land",!deletion);rotate(UiAutomation.ROTATION_FREEZE_0);if(!deletion)v.keyboard();identity(id,deletion,operation,token,stamp);if(!deletion)p.sameRaw(raw);snapshot(operation+"-return",!deletion);m.check(m.geometryInput().equals(main(deletion))&&Arrays.equals(xml,r.xml(r.load(store,id))),"new-hole recreation never adds a hole or changes existing outer/inner geometry");r.sameAssets(r.load(store,id),assets);
 if(save){m.click(deletion?"Удалить":"Применить");m.geometryReady();String edited=deletion?"0.2 4.2 51.0\n0.5 4.7 53.0\n0.7 4.5 54.0":"0.2 4.2 51.0\n0.2 4.7 52.0\n0.3 4.5 99.0\n0.7 4.7 53.0";m.check((Boolean)m.editorField("addingHole")&&m.geometryInput().equals(edited)&&Arrays.equals(xml,r.xml(r.load(store,id))),"explicit vertex action changes only unsaved new-hole input; adding-hole flag remains true");snapshot(operation+"-applied",false);p.hideKeyboard();m.click("Сохранить");m.geometryReady();Object expected=r.parse(xml),actual=r.load(store,id);Element polygon=(Element)m.element(expected,"point").getElementsByTagNameNS("*","Polygon").item(0);g.ring(polygon,"innerBoundaryIs",deletion?"4.2,0.2,51.0 4.7,0.5,53.0 4.5,0.7,54.0 4.2,0.2,51.0":"4.2,0.2,51.0 4.7,0.2,52.0 4.5,0.3,99.0 4.7,0.7,53.0 4.2,0.2,51.0");m.check(m.treeToken(expected).equals(m.treeToken(actual))&&!(Boolean)m.editorField("addingHole")&&g.key().equals("0/inner/2"),"Save adds exactly third inner boundary, never replaces outer or existing two holes");r.sameAssets(actual,assets);m.check(m.editorField("vertexDraft")==null,"applied raw new-hole intent consumed");g.ghost();}
 else{m.click("Отмена");m.check((Boolean)m.editorField("addingHole")&&m.geometryInput().equals(main(deletion))&&Arrays.equals(xml,r.xml(r.load(store,id))),"Cancel leaves original unsaved new hole intact without adding/saving anything");r.sameAssets(r.load(store,id),assets);snapshot(operation+"-cancelled",false);m.check(m.editorField("vertexDraft")==null,"cancelled raw new-hole intent cleared");g.ghost();m.check(m.editorField("vertexDraft")==null&&!p.state().getBoolean("present"),"cancelled new-hole raw modal does not reopen after actual recreation");m.check((Boolean)m.editorField("addingHole")&&m.geometryInput().equals(main(deletion))&&Arrays.equals(xml,r.xml(r.load(store,id))),"new-hole private draft survives another recreation after Cancel without becoming outer-ring edit");}v.emit("NEWHOLE_RESULT operation="+operation+" save="+save+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}

 void openIntent(long id,boolean deletion)throws Exception{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.GeometryEditorActivity").putExtra("project",id).putExtra("feature","point").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));p.rotate(UiAutomation.ROTATION_FREEZE_0);m.click("Действия");m.click("Добавить внутренний контур");m.inputs(main(deletion));m.click("Действия");m.click("Редактировать вершины");m.click("2. 0.2 4.7 52.0");m.click(deletion?"Удалить вершину":"Вставить после");if(!deletion){m.inputs("0.3 4.5 99");m.runOnMainSync(()->p.field(m.activeDialogRoot()).setSelection(1,3));v.keyboard();}}
 void changed(Object store,long id)throws Exception{Object doc=r.load(store,id);Element outer=(Element)m.element(doc,"point").getElementsByTagNameNS("*","outerBoundaryIs").item(0);((Element)outer.getElementsByTagNameNS("*","coordinates").item(0)).setTextContent("0,0,101 5,0,102 5,5,103 0,0,101");m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,doc);}
 void reject(Object store,boolean deletion,String outcome)throws Exception{long id=g.fixture(store,true);try{Object doc=r.load(store,id);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));openIntent(id,deletion);Object d=m.editorField(deletion?"geometryConfirmation":"vertexDraft");String token=(String)d.getClass().getField("token").get(d),stamp=(String)d.getClass().getField("mainStamp").get(d);JSONObject raw=deletion?null:p.state();if(outcome.equals("stale-before"))changed(store,id);rotate(UiAutomation.ROTATION_FREEZE_90);identity(id,deletion,"after",token,stamp);if(!deletion){v.keyboard();p.sameRaw(raw);}if(outcome.equals("stale-after"))changed(store,id);String newer=main(deletion);if(outcome.equals("main-changed")){newer=newer+"\n0.8 4.4 90";final String value=newer;final EditText input=(EditText)m.editorField("input");m.runOnMainSync(()->input.setText(value));m.click(deletion?"Удалить":"Применить");m.geometryReady();m.check(!(deletion?g.enabled(false):p.enabled()),"new-hole old intent immediately rejects changed main input");}rotate(UiAutomation.ROTATION_FREEZE_0);identity(id,deletion,"after",token,stamp);if(!deletion){v.keyboard();p.sameRaw(raw);}m.check(!(deletion?g.enabled(false):p.enabled())&&m.geometryInput().equals(newer)&&(Boolean)m.editorField("addingHole"),"new-hole stale/main-changed remains blocked without rebinding or overwriting newer dirty main");byte[] current=r.xml(r.load(store,id));snapshot("guard-"+(deletion?"delete-":"raw-")+outcome,!deletion);m.click("Отмена");m.check(m.geometryInput().equals(newer)&&(Boolean)m.editorField("addingHole"),"new-hole rejected Cancel preserves exact dirty main and adding flag");g.unchanged(store,id,current,assets);p.ghost();m.check(m.geometryInput().equals(newer)&&(Boolean)m.editorField("addingHole"),"new-hole cancelled guard draft retained after another actual recreation");g.unchanged(store,id,current,assets);v.emit("NEWHOLE_GUARD kind="+(deletion?"delete":"raw")+" outcome="+outcome+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void staleSave(Object store)throws Exception{long id=g.fixture(store,true);try{Object doc=r.load(store,id);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));openIntent(id,false);rotate(UiAutomation.ROTATION_FREEZE_90);m.click("Применить");m.geometryReady();String main=m.geometryInput();m.check((Boolean)m.editorField("addingHole")&&m.editorField("vertexDraft")==null,"new-hole explicit Apply consumes raw intent but does not save");changed(store,id);byte[] current=r.xml(r.load(store,id));p.hideKeyboard();m.click("Сохранить");m.geometryReady();m.waitText("Не удалось сохранить");m.check(m.geometryInput().equals(main)&&(Boolean)m.editorField("addingHole"),"new-hole stale MainSave retains local input and adding mode");g.unchanged(store,id,current,assets);snapshot("guard-stale-save",false);rotate(UiAutomation.ROTATION_FREEZE_0);m.check(m.geometryInput().equals(main)&&(Boolean)m.editorField("addingHole")&&m.editorField("vertexDraft")==null,"new-hole stale MainSave survives reverse recreation without reopening raw modal");g.unchanged(store,id,current,assets);v.emit("NEWHOLE_GUARD outcome=stale-save PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store,boolean project)throws Exception{long id=g.fixture(store,true),other=-1;try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));long target=id;if(project){Object copy=r.parse(xml);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_NEW_HOLE_FOREIGN");target=other;}openIntent(id,false);final long pid=target;final String feature=project?"point":"other";m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",pid).putExtra("feature",feature)));rotate(UiAutomation.ROTATION_FREEZE_90);m.check((Long)m.editorField("project")==target&&feature.equals(m.editorField("featureId"))&&m.editorField("vertexDraft")==null&&m.editorField("geometryConfirmation")==null&&!(Boolean)m.editorField("addingHole")&&!p.state().getBoolean("present"),"foreign project/feature drops unsaved new-hole intent and adding mode");String own=project?"0 0 1\n0 5 2\n5 5 3\n0 0 1":"22 12 32";m.check(m.geometryInput().equals(own)&&g.key().equals(project?"0/outer":"0"),"foreign context keeps only its own geometry and original address");snapshot(project?"guard-foreign-project":"guard-foreign-feature",false);rotate(UiAutomation.ROTATION_FREEZE_0);m.check(m.geometryInput().equals(own)&&m.editorField("vertexDraft")==null&&!(Boolean)m.editorField("addingHole"),"foreign reverse recreation never adopts previous new-hole input");g.unchanged(store,id,xml,assets);g.unchanged(store,target,xml,assets);v.emit("NEWHOLE_GUARD foreignProject="+project+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void invalid(Object store)throws Exception{long id=g.fixture(store,true);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));openIntent(id,false);m.inputs("91 0");m.click("Применить");m.runOnMainSync(()->p.field(m.activeDialogRoot()).setSelection(1,3));JSONObject raw=p.state();m.check(!raw.getString("error").isEmpty(),"new-hole invalid latitude produces inline error");Object d=m.editorField("vertexDraft");String token=(String)d.getClass().getField("token").get(d),stamp=(String)d.getClass().getField("mainStamp").get(d);for(int direction:new int[]{-1,UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){if(direction!=-1)rotate(direction);v.keyboard();p.sameRaw(raw);identity(id,false,"after",token,stamp);snapshot("guard-invalid-"+(direction==-1?"before":direction==UiAutomation.ROTATION_FREEZE_90?"land":"return"),true);}m.click("Отмена");m.check(m.geometryInput().equals(main(false))&&(Boolean)m.editorField("addingHole"),"invalid new-hole raw Cancel never changes own unsaved main");g.unchanged(store,id,xml,assets);p.ghost();g.unchanged(store,id,xml,assets);v.emit("NEWHOLE_GUARD outcome=invalid PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}

 void run(boolean guards)throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());AccessibilityServiceInfo service=m.getUiAutomation().getServiceInfo();int flags=service.flags;service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(service);String keyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();try{v.shell("settings put secure show_ime_with_hard_keyboard 1");if(guards){for(boolean deletion:new boolean[]{false,true})for(String outcome:new String[]{"stale-before","stale-after","main-changed"})reject(store,deletion,outcome);staleSave(store);foreign(store,true);foreign(store,false);invalid(store);}else for(String op:new String[]{"before","after","delete-save","delete-cancel"})scenario(store,op);m.check(m.requests.get()==requests,"new-hole intents stay local without tile requests");}finally{v.finish();service.flags=flags;m.getUiAutomation().setServiceInfo(service);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(keyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+keyboard);m.call(store,"close",new Class[]{});}}
}
